-- Mitesh Real Estate Solution — Supabase schema
-- Run this in the Supabase SQL editor (Dashboard → SQL Editor → New query).
-- Safe to re-run: it drops and recreates the two tables.

-- ---------------------------------------------------------------- enquiries
drop table if exists public.enquiries cascade;

create table public.enquiries (
  id          bigint generated always as identity primary key,
  ref         text        not null unique,
  name        text        not null,
  email       text        not null,
  phone       text        not null,
  property_id text,
  location    text,
  budget      text,
  message     text,
  handled     boolean     not null default false,
  created_at  timestamptz not null default now()
);

create index enquiries_created_at_idx on public.enquiries (created_at desc);
create index enquiries_property_id_idx on public.enquiries (property_id);

alter table public.enquiries enable row level security;

-- Anyone (the website, using the publishable key) may submit a lead...
create policy "anon can submit enquiries"
  on public.enquiries for insert to anon with check (true);

-- ...but nobody anonymous can read them back. Use the dashboard or a
-- service_role key on your server to view leads.
revoke select on public.enquiries from anon;

-- ---------------------------------------------------------------- properties
drop table if exists public.properties cascade;

create table public.properties (
  id           text primary key,
  title        text    not null,
  location     text    not null,
  price        bigint,
  type         text    not null,
  area         integer not null default 0,
  size_label   text,
  bedrooms     integer not null default 0,
  bathrooms    integer not null default 0,
  status       text    not null default 'Available',
  featured     boolean not null default false,
  art          text    not null default 'plot',
  rate         integer,
  rera         text,
  transaction  text,
  facing       text,
  description  text,
  amenities    jsonb   not null default '[]'::jsonb,
  images       jsonb,
  sort_order   integer not null default 0,
  published    boolean not null default true,
  updated_at   timestamptz not null default now()
);

create index properties_type_idx on public.properties (type);
create index properties_location_idx on public.properties (location);

alter table public.properties enable row level security;

-- The website reads published listings with the publishable key.
create policy "anon can read published properties"
  on public.properties for select to anon using (published);

-- Writes are dashboard / service_role only — no anon policy is defined.

