  ('MRS-1482765', 'Residential Plot in Ujjain Road, Indore', 'Ujjain Road, Indore', 1637000, 'Residential Plot', 461, '461 sq ft', 0, 0, 'Available', false, 'plot', 3550, null, 'New Property', null, 'Located on Ujjain Road in Indore, this residential plot spans across 461 sq.ft. and is now available for sale. The property is a new development, offering a blank canvas for potential homeowners to design and build their dream home from scratch. This freehold plot is situated in a prime…', '["Clear-title documentation", "Site visit arranged on a call", "Registry & loan guidance included"]'::jsonb, '[{"src": "https://rei.wlimg.com/prop_images/884036/1482765_1.jpg", "fit": "cover", "label": "Photo 1"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_2.jpg", "fit": "cover", "label": "Photo 2"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_3.jpg", "fit": "cover", "label": "Photo 3"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_4.jpg", "fit": "cover", "label": "Photo 4"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_5.jpg", "fit": "cover", "label": "Photo 5"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_6.jpg", "fit": "cover", "label": "Photo 6"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_7.jpg", "fit": "cover", "label": "Photo 7"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_8.jpg", "fit": "cover", "label": "Photo 8"}, {"src": "https://rei.wlimg.com/prop_images/884036/1482765_9.jpg", "fit": "cover", "label": "Photo 9"}]'::jsonb, 73),
